function [numericAudit, macroPath] = build_m18_report_values(evidence)
%BUILD_M18_REPORT_VALUES Generate traceable LaTeX macros from frozen data.

arguments
    evidence (1, 1) struct = load_m18_validated_artifacts
end
generatedRoot = fullfile(evidence.root, "report", "generated");
if ~isfolder(generatedRoot), mkdir(generatedRoot); end
macroPath = fullfile(generatedRoot, "m18_values.tex");
numericAudit = struct2table(localRows(evidence));
fileID = fopen(macroPath, 'w');
cleanupFile = onCleanup(@() fclose(fileID));
fprintf(fileID, '%% Generated by build_m18_report_values.m. Do not edit.\n');
for index = 1:height(numericAudit)
    fprintf(fileID, '\\newcommand{\\%s}{%s}\n', ...
        numericAudit.ReportMacro_Table(index), ...
        localTexValue(numericAudit.Value(index)));
end
end

