function row = localRow(label,value,unit,milestone,artifact,field,macro)
if isnumeric(value)||islogical(value), value=string(compose("%.12g",value)); else, value=string(value); end
row=struct('Label',string(label),'Value',value,'Unit',string(unit), ...
    'SourceMilestone',string(milestone),'SourceArtifact',string(artifact), ...
    'SourceField',string(field),'ReportMacro_Table',string(macro), ...
    'PresentationUse',"generated macro / selected slides");
end

function text = localTexValue(value)
number=str2double(value);
if ~isnan(number) && number == round(number)
    text=char(compose("%.0f",number));
    return
end
if ~isnan(number), text=char(compose("%.6g",number)); return, end
text=char(value); text=strrep(text,'_','\_'); text=strrep(text,'%','\%'); text=strrep(text,'&','\&');
end
